"""Derive kitchen_room.xml from the upstream kitchen_scene.xml VERBATIM,
removing only the Hello Robot Stretch (its <model> asset and <attach>
frame) so a different robot can be included alongside the room.

Every room, furniture, light and prop element is byte-for-byte upstream.
Re-run after updating kitchen_scene.xml:  python env/kitchen/make_room.py
"""
import re
from pathlib import Path

here = Path(__file__).parent
src = (here / "kitchen_scene.xml").read_text()

out = re.sub(r'\n\s*<model name="stretch3" file="stretch.xml"/>', "", src)
out = re.sub(r'\n\s*<!-- The Stretch 3 itself:.*?</frame>', "", out, flags=re.S)
assert 'file="stretch.xml"' not in out and "<attach " not in out, "strip failed"

header = ("<!-- GENERATED by make_room.py from kitchen_scene.xml "
          "(namenu/stretch3-kitchen-scene, Apache-2.0). Only the Stretch "
          "robot asset + attach frame are removed; do not edit by hand. -->\n")
(here / "kitchen_room.xml").write_text(header + out)
print("wrote", here / "kitchen_room.xml")
